.vc-feedback-sheet {
  position: fixed;
  inset: 0;
  z-index: 121050;
  display: grid;
  place-items: end center;
  padding: 0;
  pointer-events: none;
}
.vc-feedback-sheet[hidden] {
  display: none !important;
  pointer-events: none !important;
}
.vc-feedback-sheet:not([hidden]) {
  pointer-events: auto;
}
.vc-feedback-sheet__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  margin: 0;
  padding: 0;
  background: rgba(3, 2, 1, 0.78);
  cursor: var(--vc-cursor-pointer);
  opacity: 0;
  transition: opacity 0.18s ease;
}
.vc-feedback-sheet.is-in .vc-feedback-sheet__backdrop {
  opacity: 1;
}
.vc-feedback-sheet__panel {
  position: relative;
  z-index: 1;
  width: min(54rem, 100%);
  max-height: min(94dvh, 58rem);
  display: flex;
  flex-direction: column;
  border-radius: 1.35rem 1.35rem 0 0;
  border: 1px solid rgba(232, 201, 168, 0.32);
  background: linear-gradient(168deg, #1e1611 0%, #120e0b 52%, #0a0705 100%);
  box-shadow: 0 -18px 40px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  transform: translateY(18px);
  opacity: 0;
  transition: transform 0.16s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.16s ease;
}
.vc-feedback-sheet.is-in .vc-feedback-sheet__panel {
  transform: translateY(0);
  opacity: 1;
}
